@@ -0,0 +1,76 @@
+opam-version: "2.0"
+maintainer: "team AT robur dot coop"
+authors: ["Hannes Mehnert <hannes@mehnert.org>"]
+homepage: "https://github.com/mirage/ocaml-dns"
+doc: "https://mirage.github.io/ocaml-dns/"
+dev-repo: "git+https://github.com/mirage/ocaml-dns.git"
+bug-reports: "https://github.com/mirage/ocaml-dns/issues"
+license: "BSD-2-Clause"
+
+depends: [
+  "dune" {>= "2.8.0"}
+  "ocaml" {>= "4.13.0"}
+  "dns" {= version}
+  "dnssec" {= version}
+  "dns-tsig" {= version}
+  "dns-client-lwt" {= version}
+  "dns-server" {= version}
+  "dns-certify" {= version}
+  "dns-resolver" {= version}
+  "bos" {>= "0.2.0"}
+  "cmdliner" {>= "1.1.0"}
+  "fpath" {>= "0.7.2"}
+  "x509" {>= "1.0.0"}
+  "mirage-crypto" {>= "1.0.0"}
+  "mirage-crypto-pk" {>= "1.0.0"}
+  "mirage-crypto-rng" {>= "2.0.0"}
+  "mirage-mtime" {>= "5.0.0"}
+  "mtime" {>= "2.1.0"}
+  "ptime" {>= "1.2.0"}
+  "tcpip" {>= "8.2.0"}
+  "ohex" {>= "0.2.0"}
+  "logs" {>= "0.6.3"}
+  "fmt" {>= "0.8.8"}
+  "ipaddr" {>= "4.0.0"}
+  "lwt" {>= "4.0.0"}
+  "randomconv" {>= "0.2.0"}
+  "metrics" {>= "0.5.0"}
+  "alcotest" {with-test}
+]
+
+build: [
+  ["dune" "subst"] {dev}
+  ["dune" "build" "-p" name "-j" jobs]
+  ["dune" "runtest" "-p" name "-j" jobs] {with-test}
+  ["sh" "-ex" "app/packaging/FreeBSD/create_package.sh"] {os = "freebsd"}
+  ["sh" "-ex" "app/packaging/debian/create_package.sh"] {os-family = "debian" | os-family = "ubuntu"}
+]
+
+synopsis: "Unix command line DNS utilities"
+description: """
+'oupdate' sends a DNS update packet to a DNS server that sets 'hostname A ip'.
+For authentication via TSIG, a hmac secret needs to be provided.
+
+'ocertify' updates DNS with a certificate signing request, and polls a matching
+certificate. Best used with an letsencrypt unikernel.
+
+'onotify' sends a DNS NOTIFY packet to a DNS server.
+
+'ozone' checks consistency of a given zone file (and if the previous is provided, it also checks for monotonicity in the serial in the SOA).
+
+'odns' is a DNS client, looking up DNS records.
+
+'odnssec' does DNSsec verification during lookup of DNS records.
+
+'resolver' is a stand-alone DNS resolver.
+"""
+x-maintenance-intent: [ "(latest)" ]
+url {
+  src:
+    "https://github.com/mirage/ocaml-dns/releases/download/v10.2.7/dns-10.2.7.tbz"
+  checksum: [
+    "sha256=77e4c3d12f2f1bc40d687e52426203110788331d9f822016409be762fc7c7071"
+    "sha512=0e2614f07b713f25e0fd4418bf7f69f431eee57093cbc1cebb245422a2e9d75538ee338b68e1e4c71d8b5ffcf0e7e2630b3838fe9ec5d0b54952229b8c54df7e"
+  ]
+}
+x-commit-hash: "1fd5aa55f53d5f02a42918bf969f1d9d5f26afd3"

